  const NAV = {
    ru: ['Пользовательское соглашение', 'Политика конфиденциальности'],
    uk: ['Користувацька угода', 'Політика конфіденційності'],
    en: ['User Agreement', 'Privacy Policy'],
  };

  function render(which, lang, links) {
    const src = which === 'privacy' ? PRIVACY : OFFER;
    const d = src[lang] || src.ru;
    const fill = s => s.replace(/\{(sup|rules|privacy)\}/g, (_, k) => links[k]);
    const nav = NAV[lang] || NAV.ru;
    const tabs = `<nav class="legal-tabs"><a href="${links.rules}"${which === 'rules' ? ' class="on" aria-current="page"' : ''}>${nav[0]}</a><a href="${links.privacy}"${which === 'privacy' ? ' class="on" aria-current="page"' : ''}>${nav[1]}</a></nav>`;
    const body = d.sections.map(([h, items, id]) => `<section class="rules-card"${id ? ` id="${id}"` : ''}><h2>${h}</h2>${items.map(it => Array.isArray(it)
      ? `<ul>${it.map(li => `<li>${fill(li)}</li>`).join('')}</ul>`
      : `<p>${fill(it)}</p>`).join('')}</section>`).join('');
    return `${tabs}<div class="page-head"><h1>${d.title}</h1></div><p class="rules-upd">${d.rev}</p>${body}<p class="rules-foot">${fill(d.foot)}</p>`;
  }

  window.LEGAL = { render };
